/* A7 L1 progress; source-built from registry, not manually copied markup. */
(()=>{"use strict";const repo="https://github.com/FabinGurung/JP_A7_System_Registry_and_Knowledge_Graph";
const $=id=>document.getElementById(id);
const el=(tag,s,cls)=>{const n=document.createElement(tag);if(s!==undefined)n.textContent=String(s);if(cls)n.className=cls;return n};
let rows=[];
function dateState(s){return /FINAL_CLOSED_PASS|DELIVERED|DEPLOYED_PROVIDER_VERIFIED/.test(s||"")?"done":"open"}
function paint(){const filter=$("roadmapSearch").value.toLowerCase().trim();
const box=$("roadmapDeveloped");box.replaceChildren();
let subset=rows.filter(x=>(x.title+" "+x.id+" "+x.stage+" "+x.detail).toLowerCase().includes(filter));
subset.reverse();
for(const x of subset){const a=el("article",undefined,"rp-item");
a.append(el("small",x.id+" · "+x.stage),el("h3",x.title));
const b=el("span",x.status,"rp-status");b.dataset.state=dateState(x.status);a.append(b,el("p",x.detail||"Source record contains no summary."));box.append(a)}
if(!subset.length)box.append(el("p","No milestones match your search."));
}
fetch("data/a7-roadmap.json",{cache:"no-store"}).then(r=>{if(!r.ok)throw Error("Not found");return r.json()}).then(d=>{
if(d.schema!=="a7-roadmap-projection.v0.1"||d.owner!=="A7_ONLY"||d.kind!=="DERIVED_NOT_AUTHORITATIVE"||!Array.isArray(d.developed)||!Array.isArray(d.next_a7)||!Array.isArray(d.pinned_a7))throw Error("Invalid data source");
rows=d.developed;
$("roadmapSequence").textContent=d.current_closed_sequence.replace("A7-SEQ-","");
$("roadmapMilestones").textContent=String(rows.length);
$("roadmapBacklogCount").textContent=String(d.next_a7.length);
$("roadmapSource").textContent="A7 registry projection • source "+d.source_sha256.slice(0,12)+" • build "+d.site_build_commit.slice(0,12)+" • dated snapshot; check GitHub for live runs";
// Dated provider evidence from the owning A7 bootstrap, never a live-status claim.
const evidenceBox=$("roadmapEvidence");evidenceBox.replaceChildren();
const proof=d.verified_a7_provider_evidence;
if(proof&&proof.historical_not_live===true&&/^[0-9a-f]{40}$/.test(proof.verified_commit_sha)&&proof.conclusions&&Object.values(proof.conclusions).every(v=>v==="success")){
 evidenceBox.append(el("p",proof.sequence+" • verified historical main "+proof.verified_commit_sha.slice(0,12)+" • not live provider monitoring"));
 for(const [caption,key] of [["Registry validation","registry_run"],["Pages deployment","pages_run"],["Release safeguard","release_safeguard_run"]]){
  const run=proof[key];if(!Number.isSafeInteger(run)||run<1)continue;
  const a=el("a",caption+" · #"+run);a.href=repo+"/actions/runs/"+run;a.target="_blank";a.rel="noopener noreferrer";evidenceBox.append(a);
 }
 evidenceBox.append(el("small",proof.independent_http_body_readback?"Independent page HTTP readback recorded.":"Independent served-page HTTP readback NOT verified."));
}else evidenceBox.append(el("p","No verified A7 source-backed GitHub closeout snapshot is available; consult GitHub Actions."));
$("roadmapSearch").addEventListener("input",paint);paint();
const pinnedBox=$("roadmapPinned");pinnedBox.replaceChildren();const pinnedIds=new Set();
for(const x of d.pinned_a7){
 if(pinnedIds.has(x.id)||!d.next_a7.some(t=>t.id===x.id))throw Error("Invalid pinned task reference");
 pinnedIds.add(x.id);const a=el("article",undefined,"rp-pin");
 a.append(el("small",x.id+" · "+x.priority),el("h3",x.title),el("span",x.task_boundary,"rp-pin-boundary"),el("p",x.pin_reason),el("small","Source state: "+x.state));pinnedBox.append(a);
}
const box=$("roadmapUpcoming");box.replaceChildren();
for(const x of d.next_a7.filter(x=>!pinnedIds.has(x.id))){const a=el("article",undefined,"rp-task");a.append(el("small",x.id+" · "+x.priority),el("h3",x.title),el("span",x.state,"rp-status"),el("p",x.done_when));box.append(a)}
}).catch(()=>{$("roadmapSource").textContent="Could not read this build's roadmap; consult A7's source registry on GitHub.";});
})();

/* Cloud Orbit L1 Progress — quiet panels, readable audit trails. */
.a7-progress{max-width:1340px;padding:clamp(20px,4vw,52px);margin:auto;color:#294e68;font:14px/1.6 system-ui,sans-serif}
.rp-kicker,.rp-head span{font-size:10px;letter-spacing:.14em;font-weight:850;color:#558dad}
.rp-hero h1{font-size:clamp(37px,5.4vw,68px);letter-spacing:-.045em;line-height:1.04;margin:11px 0;color:#285675}
.rp-hero h1 em{font-style:normal;color:#5e9dbe}.rp-hero>p{max-width:790px;color:#5c7f95}
.rp-links{display:flex;flex-wrap:wrap;gap:9px;margin:20px 0}.rp-links a,.rp-machine{display:inline-block;text-decoration:none;border:1px solid #c8e1ec;background:white;padding:9px 13px;border-radius:9px;color:#2c789d;font-weight:750;font-size:12px}
.rp-stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:28px 0 12px}
.rp-stats article,.rp-panel{background:#fff;border:1px solid #cfe3ed;border-radius:16px;box-shadow:0 13px 30px #6e9fb521}
.rp-stats article{padding:18px}.rp-stats span{display:block;color:#66889d;font-size:12px}
.rp-stats strong{font-size:clamp(18px,3.5vw,32px);color:#2d7196;word-break:break-word}
.rp-provenance{color:#65899e;font-size:11px;border-bottom:1px solid #d0e2ed;padding:10px 0 17px}
.rp-layout{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(290px,1fr);align-items:start;gap:15px;margin:19px 0}
.rp-panel{padding:22px}.rp-head{display:flex;align-items:end;gap:12px;justify-content:space-between;flex-wrap:wrap}
.rp-head h2{font-size:23px;line-height:1.25;margin:5px 0}.rp-head p{color:#68879c;font-size:12px;max-width:550px}
.rp-head label{display:grid;gap:4px;color:#618298;font-size:11px;font-weight:750}
.rp-head input{border:1px solid #c9dfeb;border-radius:9px;padding:9px 11px;min-width:225px;background:#f8fdff;color:#31536a}
.rp-ledger{display:grid;gap:9px;margin-top:20px;max-height:850px;overflow-y:auto;padding-right:4px}
.rp-item,.rp-task{border:1px solid #d7e6ef;background:#f9fdff;border-radius:11px;padding:14px}
.rp-item small,.rp-task small{display:block;color:#5985a0;font-weight:750;letter-spacing:.03em;font-size:10px}
.rp-item h3,.rp-task h3{color:#295b79;font-size:15px;line-height:1.35;margin:7px 0}
.rp-item p,.rp-task p{font-size:12px;color:#68869a;margin:7px 0}
.rp-status{font-size:10px;color:#34715e;background:#e8f7f2;padding:3px 7px;border-radius:6px;display:inline-block;overflow-wrap:anywhere}
.rp-status[data-state="open"]{color:#81683b;background:#fff4e2}
.rp-tasks{display:grid;gap:10px;margin:18px 0}.rp-footer-note{font-size:12px;color:#638399}.rp-machine{margin:3px}
@media(max-width:820px){.rp-layout{grid-template-columns:1fr}}@media(max-width:480px){.rp-stats{grid-template-columns:1fr}.rp-head label,.rp-head input{width:100%;min-width:0}}

/* Same canonical task IDs; pin controls only presentation ordering. */
.rp-pinned{background:linear-gradient(120deg,#f0faff,#faf8ff);border:1px solid #cfe3ed;border-radius:15px;padding:18px 21px;margin:20px 0}.rp-pinned>div>span{color:#5488a9;font-size:10px;font-weight:800;letter-spacing:.11em}.rp-pinned h2{color:#275a78;margin:6px 0}.rp-pinned p{color:#64829a;font-size:12px}.rp-pinned-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:11px;margin-top:12px}.rp-pin{background:#fff;border:1px solid #cfdfed;border-radius:11px;padding:14px;min-width:0}.rp-pin h3{color:#2d5d7b;font-size:15px}.rp-pin small{font-size:10px;color:#64849b}.rp-pin-boundary{display:inline-block;padding:4px 7px;border:1px solid #cadaea;border-radius:7px;color:#59708e;overflow-wrap:anywhere;font-size:10px;font-weight:750}@media(max-width:920px){.rp-pinned-grid{grid-template-columns:1fr}}

/* Evidence links point to dated original GitHub Actions, not a live API. */
.rp-evidence{border:1px solid #cfe3ed;border-radius:15px;background:#fff;padding:18px 21px;margin:18px 0}.rp-evidence>div>span{font-size:10px;letter-spacing:.11em;color:#5488a9;font-weight:800}.rp-evidence h2{margin:6px 0;color:#275a78;font-size:21px}.rp-evidence p{font-size:12px;color:#64829a}.rp-evidence-links{display:flex;gap:9px;flex-wrap:wrap;align-items:center;margin-top:10px}.rp-evidence-links p{flex-basis:100%;margin:0}.rp-evidence-links a{border-radius:8px;border:1px solid #cadfed;background:#f7fcff;padding:7px 10px;font-size:12px;color:#287398;text-decoration:none;font-weight:700}.rp-evidence-links small{flex-basis:100%;font-size:11px;color:#6e8294}
